    int a[6];
    map<int, int> frequency;

    for (int i = 0; i < 6; ++i) {
        cin >> a[i];
        ++frequency[a[i]];
    }

    for (const auto& [length, count] : frequency) {
        if (count >= 4) {
            vector<int> remaining;
            int removed = 0;

