                    ++removed;
                } else {
                    remaining.push_back(value);
                }
            }

            cout << (remaining[0] == remaining[1] ? "Elephant" : "Bear") << '\n';
            return 0;
        }
    }

    cout << "Alien\n";
    return 0;
}

