#include <bits/stdc++.h>
using namespace std;

int main() {
    map<int, int> frequency;

    for (int i = 0, x; i < 6; ++i) {
        cin >> x;
        ++frequency[x];
    }

    for (auto [value, count] : frequency) {
        if (count >= 4) {
            frequency[value] -= 4;

            vector<int> remaining;
            for (auto [v, cnt] : frequency) {
                while (cnt--) remaining.push_back(v);
            }

            cout << (remaining[0] == remaining[1] ? "Elephant" : "Bear") << '\n';
            return 0;
        }
    }

    cout << "Alien\n";
    return 0;
}

