int main() {
    vector<int> a(6);
    map<int, int> count;

    for (int &x : a) {
        cin >> x;
        count[x]++;
    }

    int four = -1;
    for (const auto &[value, frequency] : count) {
        if (frequency >= 4) {
            four = value;
            break;
        }
    }

    if (four == -1) {
        cout << "Alien\n";
        return 0;
    }

    vector<int> remaining;
    int removed = 0;

    for (int x : a) {
        if (x == four && removed < 4) {
            removed++;
        } else {
            remaining.push_back(x);
        }
    }

    cout << (remaining[0] == remaining[1] ? "Elephant\n" : "Bear\n");
    return 0;
}

